1	// CLI-sourced credentials and target discovery. The GUI is a loopback control
2	// panel on the operator's own machine, so instead of pasting a token into the
3	// form, a target can name a secret_source ("gh" | "glab" | "entire") and the
4	// server pulls the credential from the operator's already-authenticated CLI
5	// at run start. The token then never appears in any request or response body,
6	// and the browser never holds it at all.
7	
8	package server
9	
10	import (
11		"bytes"
12		"context"
13		"encoding/json"
14		"fmt"
15		"net/http"
16		"net/url"
17		"os/exec"
18		"strings"
19		"sync"
20		"time"
21	)
22	
23	const cliTimeout = 15 * time.Second
24	
25	// credSource describes how to obtain a git credential from an authenticated
26	// CLI. Two shapes cover the forges: a token printer (gh, entire — stdout is
27	// the password, the username defaults to x-access-token) and a git-credential
28	// helper (glab — fed the target host on stdin, it replies with key=value lines
29	// carrying both a username and a git-scoped password, since GitLab's stored
30	// API token often lacks repository scope). Nothing user-controlled is ever
31	// executed: an unknown source is an error, never a command.
32	type credSource struct {
33		argv    []string
34		gitCred bool // speak the git credential-helper protocol over stdin/stdout
35	}
36	
37	// The gh commands pin --hostname github.com: gh honors $GH_HOST, so on a box
38	// configured for a GHES host `gh auth token` would otherwise hand back that
39	// host's token, which audience validation still allows (host is github.com) and
40	// which would then be sent to github.com as Basic Auth. Pinning the hostname
41	// keeps the token and the identity tied to the audience we validated.
42	var secretSources = map[string]credSource{
43		"gh":     {argv: []string{"gh", "auth", "token", "--hostname", "github.com"}},
44		"entire": {argv: []string{"entire", "auth", "token"}},
45		"glab":   {argv: []string{"glab", "auth", "git-credential", "get"}, gitCred: true},
46	}
47	
48	// resolveSecretSource returns (username, secret). username is "" when the
49	// source doesn't dictate one (the caller's default applies); it is set for
50	// git-credential helpers that name it (GitLab → oauth2). remote supplies the
51	// host a git-credential helper is queried for, so self-managed hosts work too.
52	func resolveSecretSource(ctx context.Context, source, remote string) (string, string, error) {
53		c, ok := secretSources[source]
54		if !ok {
55			return "", "", fmt.Errorf("unknown secret_source %q (gh | glab | entire)", source)
56		}
57		stdin := ""
58		if c.gitCred {
59			stdin = fmt.Sprintf("protocol=https\nhost=%s\n\n", credHost(remote))
60		}
61		out, err := runCLI(ctx, stdin, c.argv...)
62		if err != nil {
63			return "", "", err
64		}
65		if c.gitCred {
66			return parseGitCredential(out, strings.Join(c.argv, " "))
67		}
68		tok := strings.TrimSpace(out)
69		if tok == "" {
70			return "", "", fmt.Errorf("%s printed an empty token", strings.Join(c.argv, " "))
71		}
72		return "", tok, nil
73	}
74	
75	// validateSecretAudience pins a CLI-sourced credential to its issuer so the
76	// server won't materialize it for an unrelated target. A gh/glab token belongs
77	// to its forge; the entire subject token is POSTed to token_url and the
78	// resulting jurisdiction token is used across the cluster, so remote, token_url
79	// and jurisdiction must all stay under entire.io. Self-hosted forges should
80	// paste a token rather than name a CLI source.
81	func validateSecretAudience(source, remote, tokenURL, jurisdiction string) error {
82		// secureHost parses a URL that a CLI-sourced credential will be sent to and
83		// returns its hostname only if the URL is safe to send a token over: it must
84		// be https (a token as Basic auth over http:// leaks it on the wire) and
85		// carry no userinfo (an embedded user:pass@ would override the credential the
86		// audience check is pinning). Any deviation is an error, not a bare host, so
87		// no downstream check can accidentally accept it.
88		secureHost := func(label, raw string) (string, error) {
89			u, err := url.Parse(raw)
90			if err != nil {
91				return "", fmt.Errorf("secret_source %s: %s %q is not a valid URL: %w", source, label, raw, err)
92			}
93			if u.Scheme != "https" {
94				return "", fmt.Errorf("secret_source %s requires an https %s (a CLI token must never travel over cleartext), got %q", source, label, raw)
95			}
96			if u.User != nil {
97				return "", fmt.Errorf("secret_source %s: %s must not embed userinfo, got %q", source, label, raw)
98			}
99			return u.Hostname(), nil
100		}
101		underEntire := func(h string) bool { return h == "entire.io" || strings.HasSuffix(h, ".entire.io") }
102		// token_url/jurisdiction are Entire-only: their mere presence makes NewRunner
103		// select the Entire token-exchange path, which POSTs the resolved credential
104		// to token_url as the subject token. Paired with a gh/glab source that only
105		// validates the remote, a crafted request could resolve the GitHub/GitLab CLI
106		// token and exfiltrate it to an attacker's token_url. Bind the source to its
107		// runner mode: gh/glab must not carry these fields.
108		if (source == "gh" || source == "glab") && (tokenURL != "" || jurisdiction != "") {
109			return fmt.Errorf("secret_source %s does not use token_url/jurisdiction (those select the Entire exchange path and would send the resolved token there); omit them", source)
110		}
111		switch source {
112		case "gh":
113			h, err := secureHost("remote", remote)
114			if err != nil {
115				return err
116			}
117			if h != "github.com" {
118				return fmt.Errorf("secret_source gh is only valid for a github.com remote, not %q", remote)
119			}
120		case "glab":
121			h, err := secureHost("remote", remote)
122			if err != nil {
123				return err
124			}
125			if h != "gitlab.com" {
126				return fmt.Errorf("secret_source glab is only valid for a gitlab.com remote, not %q", remote)
127			}
128		case "entire":
129			for label, raw := range map[string]string{"remote": remote, "token_url": tokenURL, "jurisdiction": jurisdiction} {
130				h, err := secureHost(label, raw)
131				if err != nil {
132					return err
133				}
134				if !underEntire(h) {
135					return fmt.Errorf("secret_source entire requires %s under entire.io, got %q", label, raw)
136				}
137			}
138		default:
139			return fmt.Errorf("unknown secret_source %q (gh | glab | entire)", source)
140		}
141		return nil
142	}
143	
144	// credHost is the host a git-credential helper should be asked about, from the
145	// target remote; it falls back to gitlab.com so a bare "glab" source works.
146	func credHost(remote string) string {
147		if u, err := url.Parse(remote); err == nil && u.Host != "" {
148			return u.Host
149		}
150		return "gitlab.com"
151	}
152	
153	// parseGitCredential extracts username/password from a credential helper's
154	// key=value reply. Only exact "username="/"password=" lines match, so sibling
155	// keys like password_expiry_utc are ignored.
156	func parseGitCredential(out, label string) (string, string, error) {
157		var user, pass string
158		for _, line := range strings.Split(out, "\n") {
159			if v, ok := strings.CutPrefix(strings.TrimSpace(line), "username="); ok {
160				user = v
161			} else if v, ok := strings.CutPrefix(strings.TrimSpace(line), "password="); ok {
162				pass = v
163			}
164		}
165		if pass == "" {
166			return "", "", fmt.Errorf("%s returned no password (is it installed and logged in?)", label)
167		}
168		return user, pass, nil
169	}
170	
171	func runCLI(parent context.Context, stdin string, argv ...string) (string, error) {
172		ctx, cancel := context.WithTimeout(parent, cliTimeout)
173		defer cancel()
174		cmd := exec.CommandContext(ctx, argv[0], argv[1:]...)
175		if stdin != "" {
176			cmd.Stdin = strings.NewReader(stdin)
177		}
178		var stdout, stderr bytes.Buffer
179		cmd.Stdout, cmd.Stderr = &stdout, &stderr
180		if err := cmd.Run(); err != nil {
181			msg := strings.TrimSpace(stderr.String())
182			if msg == "" {
183				msg = err.Error()
184			}
185			if i := strings.IndexByte(msg, '\n'); i >= 0 {
186				msg = msg[:i]
187			}
188			return "", fmt.Errorf("%s: %s (is it installed and logged in?)", strings.Join(argv, " "), msg)
189		}
190		return strings.TrimSpace(stdout.String()), nil
191	}
192	
193	// suggestEntry is one CLI-discovered target template: a ready-to-post
194	// TargetSpec with SecretSource set and Secret empty, or the reason discovery
195	// failed. Note flags anything the operator still has to ensure themselves.
196	type suggestEntry struct {
197		Target *TargetSpec `json:"target,omitempty"`
198		Note   string      `json:"note,omitempty"`
199		Error  string      `json:"error,omitempty"`
200	}
201	
202	// handleLocalSuggest builds target templates from the operator's gh, glab, and
203	// entire CLI logins, probed concurrently. Each entry is a ready-to-post target
204	// or the reason its CLI couldn't be reached; a CLI that isn't installed or
205	// logged in just yields an Error the UI shows as a dim note.
206	func (s *Server) handleLocalSuggest(w http.ResponseWriter, r *http.Request) {
207		ctx := r.Context()
208		var gh, gitlab, entire suggestEntry
209		var wg sync.WaitGroup
210		wg.Add(3)
211		go func() { defer wg.Done(); gh = suggestGitHub(ctx) }()
212		go func() { defer wg.Done(); gitlab = suggestGitLab(ctx) }()
213		go func() { defer wg.Done(); entire = suggestEntire(ctx) }()
214		wg.Wait()
215		writeJSON(w, http.StatusOK, map[string]suggestEntry{"github": gh, "gitlab": gitlab, "entire": entire})
216	}
217	
218	func suggestGitHub(ctx context.Context) suggestEntry {
219		login, err := runCLI(ctx, "", "gh", "api", "user", "--hostname", "github.com", "--jq", ".login")
220		if err != nil {
221			return suggestEntry{Error: err.Error()}
222		}
223		repo := login + "/forgemark-target"
224		return suggestEntry{
225			Target: &TargetSpec{
226				Name:         "github",
227				Remote:       "https://github.com",
228				Repos:        []string{repo},
229				SecretSource: "gh",
230			},
231			Note: fmt.Sprintf("repo %s must exist — scripts/compare-local.sh provisions it", repo),
232		}
233	}
234	
235	func suggestGitLab(ctx context.Context) suggestEntry {
236		// glab has no --jq flag, so decode its JSON here.
237		out, err := runCLI(ctx, "", "glab", "api", "user")
238		if err != nil {
239			return suggestEntry{Error: err.Error()}
240		}
241		var u struct {
242			Username string `json:"username"`
243		}
244		if err := json.Unmarshal([]byte(out), &u); err != nil {
245			return suggestEntry{Error: fmt.Sprintf("decode glab api user: %v", err)}
246		}
247		if u.Username == "" {
248			return suggestEntry{Error: "glab api user returned no username"}
249		}
250		// gitlab.com push URL is <base>/<namespace>/<project>.git. The credential
251		// (username + git-scoped password) comes from glab's credential helper at
252		// run start, so User is left blank here. The project must be created first.
253		repo := u.Username + "/forgemark-target.git"
254		return suggestEntry{
255			Target: &TargetSpec{
256				Name:         "gitlab",
257				Remote:       "https://gitlab.com",
258				Repos:        []string{repo},
259				SecretSource: "glab",
260			},
261			Note: fmt.Sprintf("project %s must exist and be pushable — create it in GitLab first", repo),
262		}
263	}
264	
265	func suggestEntire(ctx context.Context) suggestEntry {
266		// The two CLI calls are independent (the status output is only consulted
267		// after both return), so run them concurrently — each can take up to
268		// cliTimeout, and serial worst case would double the suggest latency.
269		var (
270			status, clustersJSON   string
271			statusErr, clustersErr error
272			wg                     sync.WaitGroup
273		)
274		wg.Add(2)
275		go func() { defer wg.Done(); status, statusErr = runCLI(ctx, "", "entire", "auth", "status") }()
276		go func() {
277			defer wg.Done()
278			clustersJSON, clustersErr = runCLI(ctx, "", "entire", "api", "/api/v1/clusters")
279		}()
280		wg.Wait()
281		if statusErr != nil {
282			return suggestEntry{Error: statusErr.Error()}
283		}
284		if clustersErr != nil {
285			return suggestEntry{Error: clustersErr.Error()}
286		}
287	
288		slug := statusField(status, "Jurisdiction:")
289		loginHost := statusField(status, "Context:")
290		handle := strings.TrimPrefix(statusField(status, "User:"), "@")
291		if slug == "" || loginHost == "" || handle == "" {
292			return suggestEntry{Error: "could not parse `entire auth status` output (need Jurisdiction, Context, and User lines)"}
293		}
294		baseDomain := loginHost
295		if i := strings.Index(loginHost, ".auth."); i >= 0 {
296			baseDomain = loginHost[i+len(".auth."):]
297		}
298		var doc struct {
299			Clusters []struct {
300				Jurisdiction string `json:"jurisdiction"`
301				PublicURL    string `json:"publicUrl"`
302				IsDefault    bool   `json:"isDefault"`
303			} `json:"clusters"`
304		}
305		if err := json.Unmarshal([]byte(clustersJSON), &doc); err != nil {
306			return suggestEntry{Error: fmt.Sprintf("decode clusters: %v", err)}
307		}
308		remote := ""
309		for _, c := range doc.Clusters {
310			if c.Jurisdiction == slug && (remote == "" || c.IsDefault) {
311				remote = c.PublicURL
312			}
313		}
314		if remote == "" {
315			return suggestEntry{Error: fmt.Sprintf("no cluster in jurisdiction %q", slug)}
316		}
317	
318		repo := fmt.Sprintf("et/forgemark-%s/forgemark-target", handle)
319		return suggestEntry{
320			Target: &TargetSpec{
321				Name:         "entire-" + slug,
322				Remote:       remote,
323				Repos:        []string{repo},
324				TokenURL:     "https://" + loginHost + "/oauth/token",
325				Jurisdiction: "https://" + slug + "." + baseDomain,
326				SecretSource: "entire",
327			},
328			Note: fmt.Sprintf("repo %s must exist — FM_ENTIRE_NATIVE=1 scripts/compare-local.sh provisions it", repo),
329		}
330	}
331	
332	// statusField pulls the value after a "Label:" line prefix from the
333	// key-value block `entire auth status` prints.
334	func statusField(status, label string) string {
335		for _, line := range strings.Split(status, "\n") {
336			line = strings.TrimSpace(line)
337			if rest, ok := strings.CutPrefix(line, label); ok {
338				if fields := strings.Fields(rest); len(fields) > 0 {
339					return fields[0]
340				}
341			}
342		}
343		return ""
344	}
