1	package server
2	
3	import (
4		"context"
5		"fmt"
6		"math"
7		"math/rand"
8		"net/url"
9		"strconv"
10		"sync"
11		"time"
12	
13		"github.com/entireio/forgemark/internal/bench"
14	)
15	
16	// demoRunner synthesizes push samples so the whole pipeline — level barriers,
17	// collector, SSE, charts, persistence — can be exercised and demoed with no
18	// forge and no network. It is selected by a demo:// remote:
19	//
20	//	demo://fast?p50=80ms&spread=3&err=0.01&cas=0.02&cap=200
21	//
22	//	p50     median latency (Go duration; default 80ms)
23	//	spread  p99/p50 shape multiplier of the log-normal tail (default 3)
24	//	err     probability an op fails (default 0.01)
25	//	cas     probability an op is a CAS rejection (default 0)
26	//	cap     ops/sec saturation ceiling; approaching it inflates latency the
27	//	        way a real forge queues (default 0 = unbounded)
28	//
29	// Each concurrency level runs c goroutines that sleep a sampled latency per
30	// op, so throughput scales with concurrency until cap bends the curve — the
31	// same shapes a real sweep produces.
32	type demoRunner struct {
33		label   string
34		w       bench.Workload
35		sink    bench.Sink
36		p50     time.Duration
37		sigma   float64 // log-normal shape derived from spread
38		errRate float64
39		casRate float64
40		cap     float64
41	}
42	
43	func isDemoRemote(remote string) bool {
44		u, err := url.Parse(remote)
45		return err == nil && u.Scheme == "demo"
46	}
47	
48	func newDemoRunner(remote string, w bench.Workload, sink bench.Sink) (*demoRunner, error) {
49		u, err := url.Parse(remote)
50		if err != nil || u.Scheme != "demo" {
51			return nil, fmt.Errorf("invalid demo remote %q", remote)
52		}
53		q := u.Query()
54		d := &demoRunner{label: remote, w: w, sink: sink, p50: 80 * time.Millisecond, errRate: 0.01}
55		spread := 3.0
56		if v := q.Get("p50"); v != "" {
57			if d.p50, err = time.ParseDuration(v); err != nil || d.p50 <= 0 {
58				return nil, fmt.Errorf("demo: invalid p50 %q", v)
59			}
60		}
61		for name, dst := range map[string]*float64{"spread": &spread, "err": &d.errRate, "cas": &d.casRate, "cap": &d.cap} {
62			if v := q.Get(name); v != "" {
63				f, err := strconv.ParseFloat(v, 64)
64				// Reject NaN/±Inf explicitly: ParseFloat accepts them, and they pass a
65				// bare `f < 0` check, then poison sigma/durations and can spin a tight
66				// synthetic loop.
67				if err != nil || math.IsNaN(f) || math.IsInf(f, 0) || f < 0 {
68					return nil, fmt.Errorf("demo: invalid %s %q", name, v)
69				}
70				*dst = f
71			}
72		}
73		if spread < 1 {
74			return nil, fmt.Errorf("demo: spread must be >= 1")
75		}
76		// err and cas are probabilities per operation.
77		if d.errRate > 1 || d.casRate > 1 {
78			return nil, fmt.Errorf("demo: err and cas must be probabilities in [0,1]")
79		}
80		// For a log-normal around the median, p99 = median * exp(sigma * z99).
81		d.sigma = math.Log(spread) / 2.326
82		return d, nil
83	}
84	
85	func (d *demoRunner) Label() string        { return d.label }
86	func (d *demoRunner) Nodes() int           { return 1 }
87	func (d *demoRunner) ObjectFormat() string { return "sha1" }
88	
89	// opFor mirrors the real strategies' op mix so demo buckets exercise the same
90	// consumer paths: clone strategy emits only clones, and session emits one
91	// clone followed by SessionCommits pushes per simulated session (n is the
92	// agent's op counter).
93	func (d *demoRunner) opFor(n int) bench.OpKind {
94		switch d.w.Strategy {
95		case "clone":
96			return bench.OpClone
97		case "session":
98			if d.w.SessionCommits > 0 && n%(d.w.SessionCommits+1) == 0 {
99				return bench.OpClone
100			}
101		}
102		return bench.OpPush
103	}
104	
105	func (d *demoRunner) RunLevel(ctx context.Context, c int, barrier *bench.StartBarrier) (bench.LevelResult, error) {
106		// Saturation: offered load approaches cap → queueing inflates latency.
107		inflate := 1.0
108		if d.cap > 0 {
109			offered := float64(c) / d.p50.Seconds()
110			util := math.Min(offered/d.cap, 0.95)
111			inflate = 1 / (1 - util)
112		}
113	
114		// Wait for the shared start so the demo target's window aligns with the
115		// real targets it's compared against.
116		if barrier != nil {
117			barrier.Arrive()
118			barrier.Hold()
119		}
120	
121		// Origin both the deadline and the sample clock on the barrier's shared fire
122		// instant, exactly like bench.Runner, so scheduler delay after release can't
123		// shift or extend the demo's window past the real targets it races against
124		// (which would give it extra ops and make live buckets disagree with the
125		// final result).
126		total := d.w.Warmup + d.w.Duration
127		start := time.Now()
128		if barrier != nil {
129			start = barrier.FiredAt()
130		}
131		lctx, cancel := context.WithDeadline(ctx, start.Add(total))
132		defer cancel()
133		var mu sync.Mutex
134		var all []bench.Sample
135		var wg sync.WaitGroup
136		for i := range c {
137			wg.Add(1)
138			go func(id int) {
139				defer wg.Done()
140				// Deterministic per agent, like the engine's commit content rng.
141				rng := rand.New(rand.NewSource(int64(id)*7919 + 42)) //nolint:gosec // synthetic demo data
142				for n := 0; lctx.Err() == nil; n++ {
143					lat := time.Duration(float64(d.p50) * inflate * math.Exp(d.sigma*rng.NormFloat64()))
144					t0 := time.Now()
145					select {
146					case <-time.After(lat):
147					case <-lctx.Done():
148						return // drop the truncated op, like the engine does
149					}
150					s := bench.Sample{Offset: t0.Sub(start), Dur: time.Since(t0), Op: d.opFor(n)}
151					switch roll := rng.Float64(); {
152					case roll < d.errRate:
153						s.Res = bench.OutcomeErr
154						s.Msg = "demo: synthetic error"
155					case roll < d.errRate+d.casRate && s.Op == bench.OpPush:
156						s.Res = bench.OutcomeCAS // CAS is a ref-update outcome; clones can't CAS
157					}
158					if d.sink != nil {
159						d.sink.OnSample(s)
160					}
161					mu.Lock()
162					all = append(all, s)
163					mu.Unlock()
164				}
165			}(i)
166		}
167		wg.Wait()
168		return bench.SummarizeSamples(all, c, d.w.Strategy, 1, 1, d.w.Warmup, d.w.Duration, d.w.CommitDesc()), nil
169	}
