693	// emitBucket snapshots every collector and emits/persists one bucket. The
694	// periodic ticker calls it with force=false, which is a no-op unless a level's
695	// timed window is open (r.measuring) — so setup, cleanup, and between-level idle
696	// don't append zero/stale buckets to the timeline. The end-of-level flush calls
697	// it with force=true to emit the window's final partial second even though the
698	// window has just closed.
699	func (r *Run) emitBucket(force bool) {
700		now := time.Now().Unix()
701		// Hold r.mu across the whole tick so a level transition (which resets the
702		// collectors and advances levelIdx under the same lock) can't interleave:
703		// otherwise a snapshot could carry the previous level's samples under the
704		// new level index. The snapshot and series append are cheap and run once
705		// per second. Lock order is always r.mu → collector.mu, never reversed.
706		r.mu.Lock()
707		defer r.mu.Unlock()
708		// A bucket's OK count spans the interval since the previous bucket, which is
709		// only ~1s for a steady tick but is fractional for the first tick after the
710		// warm-up boundary and for the forced tail flush. Carry the bucket's actual
711		// measured duration so consumers plot count/duration (a true rate) instead of
712		// treating the raw count as ops/s. dt is the overlap of (lastBucketAt, now]
713		// with the measured window [windowStart+warmup, +duration], so warm-up-only
714		// buckets get 0 and the tail gets only its real remainder.
715		wallNow := time.Now()
716		measStart := r.windowStart.Add(r.bw.Warmup)
717		measEnd := measStart.Add(r.bw.Duration)
718		// A periodic tick emits only inside an open window. measuring stays true
719		// through RunLevel's post-window session-ref cleanup (up to 30s), so also
720		// gate on the deadline: past measEnd the ticks are cleanup-time buckets with
721		// zero duration and stale percentiles, which consumers would misread. The
722		// forced tail flush (force=true) still emits the window's real remainder.
723		if !force && (!r.measuring || wallNow.After(measEnd)) {
724			return
725		}
726		lo, hi := r.lastBucketAt, wallNow
727		if lo.Before(measStart) {
728			lo = measStart
729		}
730		if hi.After(measEnd) {
731			hi = measEnd
732		}
733		dtMs := int64(0)
734		if hi.After(lo) {
735			dtMs = hi.Sub(lo).Milliseconds()
736		}
737		r.lastBucketAt = wallNow
738	
739		li, c := r.levelIdx, r.levelConc
740		stats := make(map[string]BucketStats, len(r.targets))
741		for _, t := range r.targets {
742			if t.dead {
743				continue
744			}
745			st := t.col.snapshot()
746			stats[strconv.Itoa(t.id)] = st
747			if len(t.series) < maxBufferedEvents {
748				t.series = append(t.series, results.SeriesPoint{
749					T: now, DtMs: dtMs, Level: li, OK: st.OK, CAS: st.CAS, Err: st.Err,
750					P50: st.P50, P95: st.P95, P99: st.P99,
751					CloneOK: st.CloneOK, CloneErr: st.CloneErr,
752					CloneP50: st.CloneP50, CloneP95: st.CloneP95, CloneP99: st.CloneP99,
753				})
754			}
755		}
756		if len(stats) == 0 {
757			return
758		}
759		r.log.emit("bucket", map[string]any{
760			"level_index": li, "concurrency": c, "t": now, "dt_ms": dtMs, "targets": stats,
761		})
762	}
