764	func (r *Run) markDead(t *targetState, levelIdx int, err error) {
765		r.mu.Lock()
766		t.dead = true
767		t.fatalErr = err.Error()
768		r.mu.Unlock()
769		r.log.emit("target_error", map[string]any{
770			"target": t.id, "level_index": levelIdx, "message": err.Error(), "fatal": true,
771		})
772	}
