774	// aliveTargets returns the targets still participating, or nil when none are.
775	func (r *Run) aliveTargets() []*targetState {
776		r.mu.Lock()
777		defer r.mu.Unlock()
778		var out []*targetState
779		for _, t := range r.targets {
780			if !t.dead {
781				out = append(out, t)
782			}
783		}
784		return out
785	}
