12		"time"
13	
14		formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
15	)
16	
17	// Runner drives one target through concurrency levels of one workload. The
18	// caller owns the sweep loop: it calls RunLevel once per level, so level
19	// lifecycle (start/end, the returned LevelResult) is the caller's to observe —
20	// the engine only reports per-operation samples, via the optional Sink.
21	type Runner struct {
22		target Target
23		w      Workload
24		creds  credentialProvider
25		ep     *endpoint
26		httpc  *http.Client
27		sink   Sink
28	}
29	
30	// NewRunner resolves a target (credentials + endpoint; for entiredb this
31	// probes the cluster) and validates the workload against it. sink may be nil.
32	func NewRunner(ctx context.Context, t Target, w Workload, sink Sink) (*Runner, error) {
33		if err := w.Validate(); err != nil {
34			return nil, err
35		}
36		if len(t.Repos) == 0 {
37			return nil, errors.New("no repos: pass -repos or -repo-pattern + -repo-count")
38		}
39		if w.Strategy == "repo" && len(t.Repos) < 2 {
40			return nil, errors.New("strategy=repo needs >= 2 repos")
41		}
42		if t.Secret == "" {
43			return nil, errors.New("no credential secret provided")
44		}
45		httpc := newHTTPClient(t.Insecure, slices.Max(w.Concurrency)+8)
46	
47		var (
48			creds credentialProvider
49			ep    *endpoint
50			err   error
51		)
52		if t.TokenURL != "" || t.Jurisdiction != "" {
53			creds, ep, err = setupEntiredb(ctx, t, httpc)
54		} else {
55			creds, ep, err = setupGeneric(t)
56		}
57		if err != nil {
58			return nil, err
59		}
60		return &Runner{target: t, w: w, creds: creds, ep: ep, httpc: httpc, sink: sink}, nil
61	}
62	
63	// Label is the resolved endpoint label (the remote base URL), for banners and
64	// results.
65	func (r *Runner) Label() string { return r.ep.label }
66	
67	// Nodes is how many push destinations the endpoint fans out across (1 for any
68	// plain forge; the discovered replica count for entiredb).
69	func (r *Runner) Nodes() int { return len(r.ep.nodes) }
70	
71	// ObjectFormat is the resolved wire object format ("sha1" or "sha256").
72	func (r *Runner) ObjectFormat() string { return string(r.ep.objFmt) }
73	
74	// Close releases the runner's resources once its run is over: it drops idle
75	// keep-alive connections and severs the runner's reference to the credential
76	// provider, so the credential (a PAT, or an Entire subject/access token) held
77	// for the run becomes eligible for garbage collection instead of living on in a
78	// finished run kept resident in memory. Go strings can't be wiped in place, so
79	// dropping the reference is the strongest release available.
80	func (r *Runner) Close() {
81		// Stop any background token refresh before dropping the reference, or a
82		// detached exchange could keep running (and holding the token) after the run.
83		if c, ok := r.creds.(credentialCloser); ok {
84			c.close()
85		}
86		if r.httpc != nil {
87			r.httpc.CloseIdleConnections()
88		}
89		r.creds = nil
90		r.target.Secret = "" // drop the runner's own copy of the token
91	}
92	
93	// credentialCloser is an optional credentialProvider capability: release any
94	// background refresh machinery and the credentials it holds. staticCreds needs
95	// nothing; jurisdictionCreds cancels and waits for its refresh goroutine.
96	type credentialCloser interface{ close() }
97	
98	// StartBarrier synchronizes the start of one concurrency level across several
99	// runners: each Arrives once its agents are built, and the coordinator
100	// releases them together, so target-dependent setup time can't skew the
101	// measured windows of a comparison run. It tolerates a runner that fails
102	// before it is ready — that runner still Arrives, so Await can't hang. A nil
103	// barrier means "run alone, no synchronization" (the CLI's single-target path).
104	type StartBarrier struct {
105		arrived chan struct{}
106		release chan struct{}
107		n       int
108		firedAt time.Time // set before release closes; the shared start instant
109	}
110	
111	// NewStartBarrier makes a barrier expecting n participants.
112	func NewStartBarrier(n int) *StartBarrier {
113		return &StartBarrier{arrived: make(chan struct{}, n), release: make(chan struct{}), n: n}
114	}
115	
116	// Arrive reports that this participant has finished preparing (or has given up
117	// and won't Hold). The buffered channel makes it non-blocking.
118	func (b *StartBarrier) Arrive() { b.arrived <- struct{}{} }
119	
120	// Hold blocks until the coordinator fires the shared start signal.
121	func (b *StartBarrier) Hold() { <-b.release }
122	
123	// Await blocks until every participant has Arrived.
124	func (b *StartBarrier) Await() {
125		for i := 0; i < b.n; i++ {
126			<-b.arrived
127		}
128	}
129	
130	// Fire releases every held participant to begin its timed window together. It
131	// stamps firedAt before closing release, so every participant and the
132	// coordinator share one start instant (via FiredAt) rather than each reading
133	// its own time.Now after being scheduled — which would skew the sample clock
134	// against the window/dt_ms timestamps. The close is a happens-before edge, so
135	// the write is visible to every Hold() that returns.
136	func (b *StartBarrier) Fire() {
137		b.firedAt = time.Now()
138		close(b.release)
139	}
140	
141	// FiredAt is the shared start instant, valid after Fire (for the coordinator) or
142	// after Hold returns (for a participant).
143	func (b *StartBarrier) FiredAt() time.Time { return b.firedAt }
144	
145	// RunLevel runs a single concurrency level: build c agents, wait at the
146	// barrier so all targets start together, run for warmup+duration, then fold
147	// the samples into one result. It blocks for the full level window (or until
148	// ctx is cancelled). barrier may be nil to run without synchronization.
149	func (r *Runner) RunLevel(ctx context.Context, c int, barrier *StartBarrier) (LevelResult, error) {
150		var clone *cloneConfig
151		var sess *sessionConfig
152		switch r.w.Strategy {
153		case "clone":
154			clone = &cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef}
155		case "session":
156			sess = &sessionConfig{
157				cloneConfig: cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef},
158				commits:     r.w.SessionCommits,
159			}
160		}
161		agents := make([]*agent, c)
162		for i := range c {
163			repoPath := r.target.Repos[0]
164			if r.w.Strategy == "repo" {
165				repoPath = r.target.Repos[i%len(r.target.Repos)]
166			}
167			node := r.ep.nodes[i%len(r.ep.nodes)]
168			ref := DestRef(r.w.BranchPrefix, r.w.RunID, c, i)
169			a, err := newAgent(i, repoPath, node, ref, r.ep.objFmt, &r.w.Commit, r.creds, r.httpc, clone, sess, r.sink)
170			if err != nil {
171				if barrier != nil {
172					barrier.Arrive() // don't leave the coordinator's Await hanging
173				}
174				return LevelResult{}, fmt.Errorf("new agent %d: %w", i, err)
175			}
176			agents[i] = a
177		}
178	
179		// Agents are built; wait for every target before starting the clock, so the
180		// measured window begins at the same instant on each and the comparison is
181		// fair regardless of per-target setup time.
182		if barrier != nil {
183			barrier.Arrive()
184			barrier.Hold()
185		}
186	
187		total := r.w.Warmup + r.w.Duration
188		// Origin the sample clock AND the context deadline on the same instant — the
189		// barrier's shared fire time when there is one. Using FiredAt for the offset
190		// origin but a scheduled-now timeout for the deadline let a target released
191		// late run a full `total` from its late start, recording samples past the
192		// shared window end that summarize then miscounts against the fixed duration.
193		// Deriving the deadline from FiredAt()+total stops every target together.
194		// Single-target CLI runs have no barrier and just start now.
195		start := time.Now()
196		if barrier != nil {
197			start = barrier.FiredAt()
198		}
199		lvlCtx, cancel := context.WithDeadline(ctx, start.Add(total))
200		defer cancel()
201		var wg sync.WaitGroup
202		for _, a := range agents {
203			wg.Add(1)
204			go func(a *agent) {
205				defer wg.Done()
206				a.run(lvlCtx, start)
207			}(a)
208		}
209		wg.Wait()
210	
211		var all []Sample
212		for _, a := range agents {
213			all = append(all, a.samples...)
214		}
215		reposUsed := 1
216		if r.w.Strategy == "repo" {
217			reposUsed = min(c, len(r.target.Repos))
218		}
219		return summarize(all, c, r.w.Strategy, reposUsed, len(r.ep.nodes), r.w.Warmup, r.w.Duration, r.w.CommitDesc()), nil
220	}
221	
222	func setupGeneric(t Target) (credentialProvider, *endpoint, error) {
223		if t.Remote == "" {
224			return nil, nil, errors.New("-remote required (e.g. https://gitlab.com); for entiredb also pass -token-url and -jurisdiction")
225		}
226		if IsGitHubDotCom(t.Remote) && t.ObjectFmt == "sha256" {
227			return nil, nil, errors.New("github.com is sha1; drop -object-format sha256")
228		}
229		objFmt, err := parseObjectFormat(t.ObjectFmt)
230		if err != nil {
231			return nil, nil, err
232		}
233		user := t.User
234		if user == "" {
235			user = "x-access-token" // token forges ignore the username; the token is the password
236		}
237		return staticCreds{username: user, password: t.Secret}, newGenericEndpoint(t.Remote, objFmt), nil
238	}
239	
240	func setupEntiredb(ctx context.Context, t Target, httpc *http.Client) (credentialProvider, *endpoint, error) {
241		var missing []string
242		if t.Remote == "" {
243			missing = append(missing, "-remote (cluster base URL)")
244		}
245		if t.TokenURL == "" {
246			missing = append(missing, "-token-url")
247		}
248		if t.Jurisdiction == "" {
249			missing = append(missing, "-jurisdiction")
250		}
251		if len(missing) > 0 {
252			return nil, nil, fmt.Errorf("entire target (selected by -token-url/-jurisdiction) also needs: %s", strings.Join(missing, ", "))
253		}
254		clientID := t.ClientID
255		if clientID == "" {
256			clientID = "entire-cli"
257		}
258		creds := newJurisdictionCreds(httpc, t.TokenURL, t.Jurisdiction, clientID, t.Secret, "token")
259		ep, err := newEntireEndpoint(ctx, t.Remote, t.ObjectFmt, t.Repos[0], creds, httpc)
260		if err != nil {
261			return nil, nil, err
262		}
263		return creds, ep, nil
264	}
265	
266	func parseObjectFormat(s string) (formatcfg.ObjectFormat, error) {
267		switch s {
268		case "sha256":
269			return formatcfg.SHA256, nil
270		case "sha1", "auto", "": // generic doesn't probe; auto degrades to sha1
271			return formatcfg.SHA1, nil
272		default:
273			return "", fmt.Errorf("invalid -object-format %q (sha1|sha256|auto)", s)
274		}
275	}
276	
277	func newHTTPClient(insecure bool, maxConns int) *http.Client {
278		tr := &http.Transport{
279			Proxy:               http.ProxyFromEnvironment,
280			MaxIdleConns:        maxConns * 2,
281			MaxIdleConnsPerHost: maxConns,
282			MaxConnsPerHost:     0, // unbounded: don't queue pushes behind a conn cap
283			IdleConnTimeout:     90 * time.Second,
284		}
285		if insecure {
286			tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: true} //nolint:gosec // load-test opt-in
287		}
288		return &http.Client{Transport: tr, Timeout: 120 * time.Second}
289	}
