1	package bench
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"math/rand"
8		"os"
9		"strings"
10		"time"
11	
12		"github.com/go-git/go-billy/v6/memfs"
13		"github.com/go-git/go-git/v6"
14		"github.com/go-git/go-git/v6/config"
15		"github.com/go-git/go-git/v6/plumbing"
16		gitclient "github.com/go-git/go-git/v6/plumbing/client"
17		"github.com/go-git/go-git/v6/plumbing/transport"
18		"github.com/go-git/go-git/v6/storage/memory"
19	)
20	
21	// cloneConfig is the shared read-side configuration for clone and session
22	// strategies.
23	type cloneConfig struct {
24		cloneDepth int    // shallow clone depth (1 = tip only; 0 = full history)
25		baseRef    string // branch to clone; "" = remote default branch
26	}
27	
28	// sessionConfig drives the "session" strategy: each agent repeatedly
29	// shallow-clones the base branch, commits + pushes `commits` checkpoints to a
30	// fresh ephemeral branch, then abandons it and starts a new session. This
31	// interleaves read load (clone) with write load (push) on the same repo — the
32	// realistic agent shape — and exercises read/write contention (bitmap/cache
33	// invalidation under push churn) that the pure-push strategies can't.
34	type sessionConfig struct {
35		cloneConfig
36		commits int // commit+push checkpoints per cloned session
37	}
38	
39	// runClones is the agent loop for the clone strategy. Each iteration performs
40	// a shallow in-memory clone of the base branch, records one op==clone sample,
41	// then discards the repo.
42	func (a *agent) runClones(ctx context.Context, start time.Time) {
43		for ctx.Err() == nil {
44			t0 := time.Now()
45			_, _, err := a.cloneSession(ctx)
46			if ctx.Err() != nil {
47				return
48			}
49			res := readOutcome(err)
50			a.record(Sample{Offset: t0.Sub(start), Dur: time.Since(t0), Res: res, Op: OpClone, Msg: errMsg(res, err)})
51		}
52	}
53	
54	// runSessions is the agent loop for the session strategy. Clone latency is
55	// recorded as op==clone, push latency as op==push, so they're summarized
56	// separately. Ephemeral session branches (…-sN) model an agent abandoning a
57	// working branch each session.
58	func (a *agent) runSessions(ctx context.Context, start time.Time) {
59		rng := rand.New(rand.NewSource(int64(a.id)*1_000_003 + 1)) //nolint:gosec // synthetic load, not security-sensitive
60		for session := 0; ctx.Err() == nil; session++ {
61			t0 := time.Now()
62			repo, branch, err := a.cloneSession(ctx)
63			if ctx.Err() != nil {
64				return
65			}
66			res := readOutcome(err)
67			a.record(Sample{Offset: t0.Sub(start), Dur: time.Since(t0), Res: res, Op: OpClone, Msg: errMsg(res, err)})
68			if err != nil {
69				continue // clone failed — next session retries
70			}
71			a.repo = repo
72	
73			sessRef := fmt.Sprintf("%s-s%d", a.ref, session)
74			pushed := false
75			for k := 0; k < a.sess.commits && ctx.Err() == nil; k++ {
76				if err := a.commit(rng, k); err != nil {
77					a.record(Sample{Offset: time.Since(start), Res: OutcomeErr, Op: OpPush, Msg: err.Error()})
78					continue
79				}
80				t1 := time.Now()
81				perr := a.pushRef(ctx, branch, sessRef)
82				if perr == nil {
83					pushed = true // the branch now exists on the remote
84				}
85				if ctx.Err() != nil {
86					break // window closed mid-push: stop, but still clean up sessRef
87				}
88				o := classify(perr)
89				a.record(Sample{Offset: t1.Sub(start), Dur: time.Since(t1), Res: o, Op: OpPush, Msg: errMsg(o, perr)})
90			}
91			// Abandon the session branch by deleting it, so ephemeral …-sN refs don't
92			// accumulate on the target repo across the sweep (a growing receive-pack
93			// advertisement would inflate later push/clone latencies and bias the
94			// numbers). Only delete a branch we actually created, and let deleteRef
95			// run on its own context so the final session per level — reached as the
96			// window closes — is still cleaned up rather than leaked.
97			if pushed {
98				a.deleteRef(sessRef)
99			}
100		}
101	}
102	
103	// cloneSession shallow-clones the base branch into a fresh in-memory repo and
104	// returns the local branch to commit on. An empty remote degrades to an orphan
105	// (no read load) so the mode still runs against an unseeded repo.
106	func (a *agent) cloneSession(ctx context.Context) (*git.Repository, plumbing.ReferenceName, error) {
107		clone := a.cloneConfig()
108		if clone == nil {
109			return nil, "", errors.New("clone config missing")
110		}
111		auth, err := a.creds.basicAuth(ctx, a.repoPath)
112		if err != nil {
113			return nil, "", err
114		}
115		// Seed the storer's object format (matches initRepo for branch/repo). go-git
116		// only auto-negotiates SHA256 on the plain-clone path (HEAD=refs/heads/.invalid);
117		// a CloneContext into a default storer silently falls back to SHA1, so a
118		// SHA256 cluster would break here. a.objFmt comes from the same advertisement
119		// probe, so this also fixes the empty-remote (git.Open) degraded path below.
120		storer := memory.NewStorage(memory.WithObjectFormat(a.objFmt))
121		wt := memfs.New()
122		opts := &git.CloneOptions{
123			URL:          verbatimURLFor(a.node, a.repoPath),
124			Depth:        clone.cloneDepth,
125			SingleBranch: true,
126			ClientOptions: []gitclient.Option{
127				gitclient.WithHTTPClient(a.httpc),
128				gitclient.WithHTTPAuth(auth),
129			},
130		}
131		if clone.baseRef != "" {
132			opts.ReferenceName = normalizeBaseRef(clone.baseRef)
133		}
134		repo, err := git.CloneContext(ctx, storer, wt, opts)
135		if errors.Is(err, transport.ErrEmptyRemoteRepository) {
136			// CloneContext still initialised the storer + origin remote; open it and
137			// commit on an unborn master so the session runs without a real base.
138			repo, err = git.Open(storer, wt)
139			if err != nil {
140				return nil, "", fmt.Errorf("open empty clone: %w", err)
141			}
142			return repo, plumbing.ReferenceName("refs/heads/master"), nil
143		}
144		if err != nil {
145			return nil, "", fmt.Errorf("clone: %w", err)
146		}
147		head, err := repo.Head()
148		if err != nil {
149			return nil, "", fmt.Errorf("resolve head: %w", err)
150		}
151		return repo, head.Name(), nil
152	}
153	
154	func (a *agent) cloneConfig() *cloneConfig {
155		if a.clone != nil {
156			return a.clone
157		}
158		if a.sess != nil {
159			return &a.sess.cloneConfig
160		}
161		return nil
162	}
163	
164	// pushRef force-pushes the local working branch to a session-scoped remote ref.
165	func (a *agent) pushRef(ctx context.Context, src plumbing.ReferenceName, dst string) error {
166		auth, err := a.creds.basicAuth(ctx, a.repoPath)
167		if err != nil {
168			return err
169		}
170		err = a.repo.PushContext(ctx, &git.PushOptions{
171			RemoteName: "origin",
172			RefSpecs:   []config.RefSpec{config.RefSpec("+" + src.String() + ":" + dst)},
173			Force:      true,
174			ClientOptions: []gitclient.Option{
175				gitclient.WithHTTPClient(a.httpc),
176				gitclient.WithHTTPAuth(auth),
177			},
178		})
179		if err != nil {
180			return fmt.Errorf("push: %w", err)
181		}
182		return nil
183	}
184	
185	// deleteRef best-effort deletes an ephemeral session branch via an empty-source
186	// refspec, so refs don't accumulate on the target repo across a sweep. It runs
187	// on its OWN short-lived context, not the caller's per-level ctx: the final
188	// session of each level is cleaned up as the measurement window closes, when the
189	// level ctx is already done — using that dead ctx would no-op the delete and
190	// leak the ref. It is cleanup, not a measured operation.
191	func (a *agent) deleteRef(dst string) {
192		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
193		defer cancel()
194		auth, err := a.creds.basicAuth(ctx, a.repoPath)
195		if err != nil {
196			fmt.Fprintf(os.Stderr, "forgemark: delete session ref %s: auth: %v\n", dst, err)
197			return
198		}
199		if err := a.repo.PushContext(ctx, &git.PushOptions{
200			RemoteName: "origin",
201			RefSpecs:   []config.RefSpec{config.RefSpec(":" + dst)},
202			ClientOptions: []gitclient.Option{
203				gitclient.WithHTTPClient(a.httpc),
204				gitclient.WithHTTPAuth(auth),
205			},
206		}); err != nil {
207			// Best-effort: a failed delete just leaves one ref behind.
208			fmt.Fprintf(os.Stderr, "forgemark: delete session ref %s failed: %v\n", dst, err)
209		}
210	}
211	
212	// normalizeBaseRef accepts either a fully-qualified ref ("refs/heads/main") or a
213	// bare branch name ("main") and returns the fully-qualified ReferenceName that
214	// go-git's clone requires, so `-base-ref main` works as the help text implies.
215	func normalizeBaseRef(ref string) plumbing.ReferenceName {
216		if strings.HasPrefix(ref, "refs/") {
217			return plumbing.ReferenceName(ref)
218		}
219		return plumbing.NewBranchReferenceName(ref)
220	}
221	
222	// readOutcome maps a clone/fetch result to an Outcome (reads have no CAS).
223	func readOutcome(err error) Outcome {
224		if err == nil {
225			return OutcomeOK
226		}
227		return OutcomeErr
228	}
