37	// Regression: an expired token must re-exchange synchronously AND must not leak
38	// the refreshing flag. Leaking it permanently disabled ahead-of-expiry refresh,
39	// reintroducing the synchronized refresh stall the design avoids.
40	func TestJurisdictionCredsExpiredReexchangesWithoutLeakingFlag(t *testing.T) {
41		var calls atomic.Int32
42		j := newTestJurisdictionCreds(t, &calls)
43		j.tok = tokenEntry{token: "stale", exp: time.Now().Add(-time.Second)}
44	
45		got, err := j.get(context.Background())
46		if err != nil || got != "fresh" {
47			t.Fatalf("get = %q, %v; want a freshly exchanged token", got, err)
48		}
49		if calls.Load() != 1 {
50			t.Fatalf("exchanged %d times; want exactly 1 (blocking refresh)", calls.Load())
51		}
52		j.mu.Lock()
53		leaked := j.refreshing
54		j.mu.Unlock()
55		if leaked {
56			t.Fatal("refreshing flag leaked on the expired path → ahead-refresh permanently disabled")
