1	// History: browse results/*.json (CLI and server runs alike) and overlay any
2	// selection as sweep curves — ops/s vs concurrency and p95 vs concurrency.
3	// A single selected run with a stored live series also replays its timeline.
4	
5	import { h } from '../dom.js';
6	import { api } from '../api.js';
7	import { sweepChart, timeChart, targetColor, fmtNum, fmtMs } from '../charts.js';
8	
9	// preselect (from #history/<file-or-run-id>) checks that run on load, so a
10	// finished run can deep-link straight into its comparison view.
11	export function renderHistory(app, preselect) {
12	  const selected = new Map(); // file → doc
13	  const listBox = h('div', { class: 'card' }, h('div', { class: 'empty' }, 'Loading…'));
14	  const compareBox = h('div');
15	  let liveCharts = [];
16	
17	  app.append(
18	    h('h1', {}, 'History'),
19	    h('p', { class: 'sub' }, 'Every stored result — CLI and GUI runs alike. Select runs to overlay their sweep curves.'),
20	    listBox, compareBox);
21	
22	  async function toggle(file, checked) {
23	    if (checked) {
24	      try { selected.set(file, await api.historyDoc(file)); }
25	      catch (err) { alert(String(err.message || err)); return; }
26	    } else {
27	      selected.delete(file);
28	    }
29	    renderCompare();
30	  }
31	
32	  function seriesList() {
33	    // One series per (run, target): identity is stable across both charts.
34	    const out = [];
35	    for (const [file, doc] of selected) {
36	      for (const t of doc.targets || []) {
37	        if (!t.levels || !t.levels.length) continue;
38	        const runTag = selected.size > 1 ? ` (${doc.run_id || file})` : '';
39	        out.push({ label: `${t.name || 'target'}${runTag}`, target: t });
40	      }
41	    }
42	    return out.map((s, i) => ({ ...s, color: targetColor(i) }));
43	  }
44	
45	  function renderCompare() {
46	    for (const c of liveCharts) c.destroy && c.destroy();
47	    liveCharts = [];
48	    compareBox.innerHTML = '';
49	    const series = seriesList();
50	    if (!series.length) return;
51	
52	    const mkCard = (title, note) => {
53	      const el = h('div');
54	      compareBox.append(h('div', { class: 'card chart-card' },
55	        h('div', { class: 'chart-head' }, h('h2', {}, title), h('span', { class: 'u-note' }, note)), el));
56	      return el;
57	    };
58	
59	    liveCharts.push(sweepChart(mkCard('Throughput vs concurrency', 'successful ops/s per level (x is log₂)'), {
60	      seriesData: series.map((s) => ({
61	        label: s.label, color: s.color,
62	        points: s.target.levels.map((l) => [l.concurrency, l.ops_per_sec]),
63	      })),
64	      unit: fmtNum,
65	    }));
66	    liveCharts.push(sweepChart(mkCard('p95 latency vs concurrency', 'per-op p95 in the measured window'), {
67	      seriesData: series.map((s) => ({
68	        label: s.label, color: s.color,
69	        points: s.target.levels.map((l) => [l.concurrency, l.p95_ms]),
70	      })),
71	      unit: fmtMs,
72	    }));
73	
74	    // Timeline replay when exactly one run is selected and it stored series.
75	    if (selected.size === 1) {
76	      const doc = [...selected.values()][0];
77	      const withSeries = (doc.targets || []).filter((t) => t.series && t.series.length);
78	      if (withSeries.length) {
79	        const tputEl = mkCard('Timeline replay — throughput', 'stored 1s buckets from the live run');
80	        const latEl = mkCard('Timeline replay — p95 latency', 'rolling 10s window as recorded');
81	        const colors = new Map(seriesList().map((s) => [s.target, s.color]));
82	        const isClone = doc.strategy === 'clone';
83	        // A periodic bucket and the forced tail flush can share the same
84	        // whole-second t. Aggregate points per t (sum counts and durations, keep
85	        // the latest rolling percentile) so replay doesn't silently drop the
86	        // tail's operations, and normalize count/duration to a true ops/s rate.
87	        // Legacy series without dt_ms fall back to a 1s bucket.
88	        // Aggregate by (t, level), keyed on both: within one level a periodic
89	        // bucket and the tail flush can share a second and must merge, but two
90	        // different levels sharing a boundary second must NOT be blended (summed
91	        // counts/durations with a single surviving percentile) — nor may one be
92	        // dropped. Both are retained as distinct slots, plotted at x = t nudged
93	        // by level so a shared second shows both points instead of losing one.
94	        const aggOf = (series) => {
95	          const byKey = new Map();
96	          for (const p of series) {
97	            const lvl = p.level ?? 0;
98	            const k = p.t + '|' + lvl;
99	            const a = byKey.get(k) || { t: p.t, level: lvl, ok: 0, clone_ok: 0, dt: 0, last: p };
100	            a.ok += p.ok || 0;
101	            a.clone_ok += p.clone_ok || 0;
102	            a.dt += p.dt_ms || 1000;
103	            a.last = p;
104	            byKey.set(k, a);
105	          }
106	          return byKey;
107	        };
108	        const aggs = new Map(withSeries.map((t) => [t, aggOf(t.series)]));
109	        // Union of every (t, level) slot across targets, ordered by second then
110	        // level. x = t + level/1000 keeps slots in the same second distinct and
111	        // strictly increasing so uPlot renders each; the offset is sub-second so
112	        // it still reads as that second on a time axis.
113	        const slots = [...new Set(withSeries.flatMap((t) => [...aggs.get(t).keys()]))]
114	          .map((k) => { const [ts, lvl] = k.split('|').map(Number); return { k, t: ts, level: lvl }; })
115	          .sort((a, b) => a.t - b.t || a.level - b.level);
116	        const mkRows = (val) => slots.map((s) => [s.t + s.level / 1000, ...withSeries.map((t) => {
117	          const a = aggs.get(t).get(s.k);
118	          return a ? val(a) : null;
119	        })]);
120	        const rateOf = (a) => {
121	          const dt = a.dt / 1000;
122	          const n = isClone ? a.clone_ok : a.ok;
123	          return dt > 0 ? n / dt : null;
124	        };
125	        // Gate on the recorded rolling p95, not this second's completions, so a
126	        // quiet bucket doesn't drop a point the stored window still covered.
127	        const p95Of = (a) => {
128	          const p = isClone ? a.last.clone_p95_ms : a.last.p95_ms;
129	          return p > 0 ? p : null;
130	        };
131	        const tput = timeChart(tputEl, { series: withSeries.map((t) => ({ label: t.name, color: colors.get(t) || targetColor(0) })), unit: fmtNum });
132	        tput.setAll(mkRows(rateOf));
133	        const lat = timeChart(latEl, { series: withSeries.map((t) => ({ label: t.name, color: colors.get(t) || targetColor(0) })), unit: fmtMs });
134	        lat.setAll(mkRows(p95Of));
135	        liveCharts.push(tput, lat);
136	      }
137	    }
138	  }
139	
140	  api.history().then((items) => {
141	    listBox.innerHTML = '';
142	    if (!items || !items.length) {
143	      listBox.append(h('div', { class: 'empty' }, 'No results yet. Finished runs land here as JSON docs.'));
144	      return;
145	    }
146	    for (const it of items) {
147	      const cb = h('input', { type: 'checkbox', style: { width: 'auto' }, onchange: (e) => toggle(it.file, e.target.checked) });
148	      if (preselect && (it.file === preselect || it.run_id === preselect)) {
149	        cb.checked = true;
150	        toggle(it.file, true);
151	      }
152	      listBox.append(h('div', { class: 'hist-row' },
153	        cb,
154	        h('span', { class: 'file' }, it.run_id || it.file),
155	        it.state ? h('span', { class: `badge ${it.state}` }, it.state) : null,
156	        h('span', { class: 'meta' }, `${it.strategy} · ${(it.targets || []).join(' vs ') || '—'} · ${it.levels} level${it.levels === 1 ? '' : 's'}`),
157	        h('span', { class: 'spacer' }),
